const fmt=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0});const money=v=>v==null?'Нет данных':fmt.format(v)+' ₽';const date=v=>v?new Date(v).toLocaleDateString('ru-RU'):'—';const costLabels={survey:'Межевание',registration:'Оформление и регистрация',geodesist:'Геодезические работы',tax:'Налоги',other:'Дополнительные расходы'};
const safeURL=s=>{try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}};
async function api(path,options={}){const r=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const v=await r.json();if(!r.ok)throw Error(v.error||'Не удалось выполнить действие');return v;}
function App(){
 const [data,setData]=useState(emptyState),[loaded,setLoaded]=useState(false),[user,setUser]=useState(null),[error,setError]=useState(''),[toast,setToast]=useState(''),[page,setPage]=useState('search'),[demo,setDemo]=useState(false),[region,setRegion]=useState(REGIONS[0]),[territory,setTerritory]=useState(''),[kind,setKind]=useState('unformed'),[usages,setUsages]=useState([...USAGES]),[minArea,setMinArea]=useState(6),[maxArea,setMaxArea]=useState(20),[view,setView]=useState('split'),[sort,setSort]=useState('default'),[query,setQuery]=useState(''),[selection,setSelection]=useState(null),[mobileFilters,setMobileFilters]=useState(false),[mobileMenu,setMobileMenu]=useState(false),[busy,setBusy]=useState(false),[bounds,setBounds]=useState(null),[draw,setDraw]=useState(false),[searchResult,setSearchResult]=useState(null),[docsBusy,setDocsBusy]=useState(false),[review,setReview]=useState(null),[pickedDocs,setPickedDocs]=useState([]),[modal,setModal]=useState(null),[manual,setManual]=useState({region:REGIONS[0],settlement:'',address:'',area:10,usage:'ИЖС',lat:'',lng:'',kind:'unformed'});
 const xlsxRef=useRef(),pdfRef=useRef(),geoRef=useRef();
 useEffect(()=>{api('bootstrap').then(r=>{setData(r.state);setUser(r.user);setDemo(r.user.auth!=='password');setLoaded(true);}).catch(e=>{setError(e.message);setLoaded(true);});},[]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(t);}},[toast]);
 const mutate=async(action,payload)=>{const r=await api('mutate',{method:'POST',body:JSON.stringify({action,payload})});setData(r.state);return r;};
 const run=fn=>async(...args)=>{try{await fn(...args);}catch(e){setToast(e.message);}};
 const demos=useMemo(()=>demoParcels(region,kind),[region,kind]);
 const sourceParcels=demo?demos:data.parcels.filter(p=>!p.demo);
 let parcels=sourceParcels.filter(p=>(page!=='favorites'||p.favorite)&&p.region===region&&p.kind===kind&&usages.includes(p.usage)&&p.area>=Number(minArea)&&p.area<=Number(maxArea)&&(!query||`${p.id} ${p.address} ${p.settlement}`.toLowerCase().includes(query.toLowerCase()))&&(!territory||`${p.settlement} ${p.address}`.toLowerCase().includes(territory.toLowerCase()))&&(!bounds||(p.lat>=bounds.south&&p.lat<=bounds.north&&p.lng>=bounds.west&&p.lng<=bounds.east)));
 if(sort==='profit')parcels=[...parcels].sort((a,b)=>(calculate(b).profit??-Infinity)-(calculate(a).profit??-Infinity));if(sort==='area')parcels=[...parcels].sort((a,b)=>a.area-b.area);
 const selected=selection?(demo?demos:data.parcels).find(p=>p.id===selection):null;
 const savedDemo=useRef(new Set());const [demoFavTick,setDemoFavTick]=useState(0);if(demo){parcels=parcels.map(p=>({...p,favorite:savedDemo.current.has(p.id)}));if(page==='favorites')parcels=demos.filter(p=>savedDemo.current.has(p.id)).map(p=>({...p,favorite:true}));}
 const favorite=run(async p=>{if(p.demo){savedDemo.current.has(p.id)?savedDemo.current.delete(p.id):savedDemo.current.add(p.id);setDemoFavTick(x=>x+1);setToast('Демо-избранное обновлено · рабочая история не изменена');return;}await mutate('favorite',{id:p.id});});
 async function search(){if(!usages.length)throw Error('Выбери хотя бы один вид использования');if(Number(minArea)<6||Number(maxArea)>20||Number(minArea)>Number(maxArea))throw Error('Площадь должна быть от 6 до 20 соток');setBusy(true);setMobileFilters(false);try{if(demo){setSearchResult({status:'demo',count:parcels.length});setToast('Показаны вымышленные примеры. Реальный поиск не выполнялся.');return;}const r=await api('search',{method:'POST',body:JSON.stringify({region,territory,kind,usages,minArea:Number(minArea),maxArea:Number(maxArea),bounds})});setData(r.state);setSearchResult(r.search);setToast(r.search.message);}finally{setBusy(false);}}
 async function excelExport(items){if(!items.length)throw Error('Нет участков для выгрузки');const XLSX=await import('xlsx');const rows=items.map(p=>{const c=calculate(p);return {'ID участка':p.id,'Демонстрация':p.demo?'Да, сведения вымышлены':'Нет','Регион':p.region,'Населённый пункт':p.settlement,'Адрес':p.address,'Площадь, соток':p.area,'ВРИ':p.usage,'Широта':p.lat,'Долгота':p.lng,'Кадастровый номер':p.cadastre||'','Дата выгрузки':new Date().toISOString(),'Цена права аренды':c.price,'Расходы':c.total,'Расчётная прибыль':c.profit,'Сделок':c.deals,'Номер заявления':'','Дата подачи':'','Орган подачи':''};});const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Участки');const checks=items.flatMap(p=>p.checks.map(c=>({'ID участка':p.id,'Проверка':c.name,'Статус':c.status==='unknown'?'Требует проверки':c.status==='warning'?'Обнаружено ограничение':'По доступным данным','Описание':c.detail,'Источник':c.source||'Не указан','Дата проверки':c.checkedAt||''})));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(checks),'Проверки');const analogs=items.flatMap(p=>(p.analogs||[]).map(a=>({'ID участка':p.id,...a})));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(analogs),'Аналоги');XLSX.writeFile(wb,'Земля-участки-'+new Date().toISOString().slice(0,10)+'.xlsx');setToast('Excel скачан. Сохрани столбец ID при заполнении заявлений.');}
 function printParcel(p){const w=window.open('','_blank');if(!w)throw Error('Разреши открытие окна для печати PDF');const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const c=calculate(p);w.document.write(`<html lang="ru"><head><meta charset="utf-8"><title>${esc(p.id)}</title><style>body{font:14px Arial;color:#193c32;max-width:820px;margin:40px auto}h1{font-size:28px}table{width:100%;border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid #ddd;padding:10px}small{color:#666}svg{width:100%;height:120px}</style></head><body><small>ЗЕМЛЯ · НАВИГАТОР / ${new Date().toLocaleString('ru-RU')}</small><h1>${esc(p.settlement)}</h1><p>${p.demo?'ДЕМОНСТРАЦИЯ. ВСЕ СВЕДЕНИЯ ВЫМЫШЛЕНЫ.':''}</p><p>${esc(p.id)} · ${esc(p.address)} · ${esc(p.area)} соток · ${esc(p.usage)}</p><p>Координаты: ${esc(p.lat)}, ${esc(p.lng)}. <a href="https://www.openstreetmap.org/?mlat=${Number(p.lat)}&mlon=${Number(p.lng)}#map=16/${Number(p.lat)}/${Number(p.lng)}">Расположение на карте</a></p><h2>Проверки</h2><table>${p.checks.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.detail)}</td><td>${esc(x.source||'Источник не указан')}<br>${esc(x.checkedAt)}</td></tr>`).join('')}</table><h2>Предварительная экономика</h2><table>${[['Цена права аренды',money(c.price)],['Расходы',money(c.total)],['Расчётная чистая прибыль',money(c.profit)],['Доходность',c.roi==null?'Нет данных':c.roi.toFixed(1)+'%']].map(x=>`<tr><td>${esc(x[0])}</td><td>${esc(x[1])}</td></tr>`).join('')}</table><p>Формула: меньшая медиана за сотку × 0,8 ÷ 2 × ${esc(p.area)} соток.</p><p>${c.deals<3?'Недостаточно данных для оценки ликвидности.':''}</p><h2>Источники цен</h2><table>${c.included.map(a=>`<tr><td>${esc(a.source)}</td><td>${esc(a.date)}</td><td>${esc(money(a.price))}</td><td>${esc(a.url)}</td></tr>`).join('')}</table><h2>Нормативное основание</h2><p>${esc(p.economics?.documentTitle||'Не выбрано')}<br>${esc(p.economics?.documentClause)}<br>${esc(p.economics?.documentUrl)}</p><p>Актуальность: ${esc(p.economics?.verifiedAt||'не подтверждена')}. Расчёт предварительный. Доступность участка и доходность не гарантируются.</p><script>window.onload=()=>window.print()</script></body></html>`);w.document.close();}
 async function importExcel(e){const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>10*1024*1024)throw Error('Максимальный размер Excel — 10 МБ');const XLSX=await import('xlsx');const wb=XLSX.read(await f.arrayBuffer(),{type:'array',cellDates:true});const rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});setModal({type:'excel',rows});}
 async function uploadPDF(e){const files=[...e.target.files];e.target.value='';setDocsBusy(true);try{const pdfjs=await import('pdfjs-dist/legacy/build/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('pdfjs-dist/legacy/build/pdf.worker.min.mjs',import.meta.url).href;for(const f of files){if(f.size>10*1024*1024)throw Error('PDF должен быть не больше 10 МБ');const bytes=await f.arrayBuffer();const pdf=await pdfjs.getDocument({data:new Uint8Array(bytes)}).promise;if(pdf.numPages>100)throw Error('Поддерживаются документы до 100 страниц');let text='';for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i);const t=await p.getTextContent();text+=t.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('')+'\n';}const fields=parseReply(text);const matches=data.applications.filter(a=>a.number===fields.applicationNumber);if(matches.length===1)fields.parcelId=matches[0].parcelId;let binary='';new Uint8Array(bytes).forEach(b=>binary+=String.fromCharCode(b));await mutate('document',{name:f.name,base64:btoa(binary),text:text.slice(0,100000),fields});}setToast('Документы разобраны. Проверь поля перед подтверждением.');setPage('documents');}finally{setDocsBusy(false);}}
 async function addManual(){if(!manual.settlement.trim())throw Error('Укажи населённый пункт');if(!Number.isFinite(Number(manual.lat))||!Number.isFinite(Number(manual.lng))||!manual.lat||!manual.lng)throw Error('Укажи координаты');await mutate('parcel',{...manual,area:Number(manual.area),lat:Number(manual.lat),lng:Number(manual.lng)});setDemo(false);setRegion(manual.region);setKind(manual.kind);setModal(null);setToast('Участок добавлен. Проверки ожидают данных.');}
 async function importGeo(e){const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>5*1024*1024)throw Error('Файл должен быть до 5 МБ');const json=JSON.parse(await f.text());const r=await mutate('geojson',json);setDemo(false);setToast('Загружены участки: '+r.count);}
 const headings={search:['Поиск и экономика','Населённый пункт или кадастровый номер → контуры → расчёт'],favorites:['Избранное','Участки, к которым стоит вернуться'],history:['История поисков','Каждый поиск сохранён, ни одна находка не потеряна'],applications:['Заявления','От найденного участка до зарегистрированного права'],documents:['Ответы администраций','Проверь извлечённые данные перед сохранением'],stats:['Статистика','Результаты работы в цифрах'],settings:['Источники и доступ','Прозрачное состояние подключений']};
 const simpleMode=page==='search'&&user?.auth==='password'&&!demo;
 useEffect(()=>{window.scrollTo({top:0,behavior:'instant'})},[page]);
 const pending=data.documents.filter(d=>!d.confirmed);const stats={parcels:data.parcels.filter(p=>!p.demo).length,apps:data.applications.length,refused:data.applications.filter(a=>a.stage==='Отказ').length,agreed:data.applications.filter(a=>a.stage==='Предварительное согласование').length};
 return <div className="app-shell"><aside className={'sidebar '+(mobileMenu?'open':'')}><a className="brand" href="#" onClick={e=>{e.preventDefault();setPage('search')}}><span className="brand-symbol"><Layers size={26}/></span><span>земля<span className="brand-sub">НАВИГАТОР</span></span></a><button className="mobile-close icon-btn" onClick={()=>setMobileMenu(false)} aria-label="Закрыть меню"><X/></button><div className="workspace-tag"><span className="avatar">М</span><div>Моё пространство<small>Личный кабинет</small></div><ShieldCheck size={16}/></div><div className="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav>{[['search',Search,'Поиск участков'],['favorites',Heart,'Избранное'],['history',History,'История поисков'],['applications',FolderOpen,'Заявления'],['documents',FileText,'Документы'],['stats',BarChart3,'Статистика']].map(([id,Icon,label])=><button key={id} className={'nav-item '+(page===id?'active':'')} onClick={()=>{setPage(id);setSelection(null);setMobileMenu(false)}}><Icon size={19}/><span>{label}</span>{id==='documents'&&pending.length>0?<b>{pending.length}</b>:id==='favorites'?<small>{demo?savedDemo.current.size:data.parcels.filter(p=>p.favorite).length}</small>:null}</button>)}</nav><div className="sidebar-bottom"><div className="region-note"><Compass size={23}/><strong>Большие возможности<br/>начинаются с земли</strong><p>9 регионов. Один рабочий кабинет.</p></div><button className={'nav-item '+(page==='settings'?'active':'')} onClick={()=>{setPage('settings');setMobileMenu(false)}}><Settings size={19}/>Источники и доступ</button><div className="profile"><div className="profile-icon">М</div><div><b>Мой кабинет</b><small>{user?.email||'Закрытое пространство'}</small></div><a href="/signout-with-chatgpt?return_to=/" target="_top" aria-label="Выйти"><LogOut size={16}/></a></div></div></aside>
 <main className="main"><header className="topbar"><button className="icon-btn mobile-only" onClick={()=>setMobileMenu(true)} aria-label="Открыть меню"><Menu/></button><div className="breadcrumb">Рабочее пространство <ChevronRight size={14}/><b>{headings[page][0]}</b></div><div className="top-actions"><span className="private"><span className="dot"/>Личный доступ</span><button className={'mode-switch '+(demo?'demo':'')} onClick={()=>{setDemo(!demo);setSelection(null);setSearchResult(null);}}><span className="dot"/>{demo?'Демо-режим':'Рабочий режим'}<ChevronDown size={13}/></button><span className="top-avatar">М</span></div></header>
 <div className="page"><div className="page-heading"><div><div className="eyebrow">ЗЕМЛЯ · ДАННЫЕ · РЕШЕНИЯ</div><h1>{headings[page][0]}<span className="heading-dot">.</span></h1><p>{headings[page][1]}</p></div>{!simpleMode&&<button className="btn secondary heading-button" onClick={run(()=>excelExport(parcels))}><Download size={16}/>Выгрузить Excel</button>}</div>
 {page==='settings'&&user?.auth==='password'&&!user.emailVerifiedAt&&<div className="notice subtle"><Info size={18}/><div><b>Подтверди электронную почту</b><p>Кабинет создан. Подключи Mail.ru и запроси письмо со ссылкой подтверждения.</p><a className="text-link" href="/account/email">Настроить почту и подтверждение <ArrowRight size={14}/></a></div></div>}

 {error&&<div className="notice warning"><AlertTriangle size={18}/><div><b>Не удалось загрузить кабинет</b><p>{error}</p><button onClick={()=>location.reload()}>Повторить</button></div></div>}
 {demo&&<div className="demo-banner"><div className="demo-icon"><Layers size={17}/></div><div><b>Знакомство с навигатором</b><span>На карте — вымышленные участки. Реальные проверки и история не изменяются.</span></div><button onClick={()=>{setDemo(false);setSelection(null);setSearchResult(null)}}>К работе <ArrowRight size={15}/></button></div>}
 {!loaded?<div className="empty"><Loader2 className="spin"/><h3>Загружаем пространство…</h3></div>:<>
 {simpleMode&&<SimpleLandSearch parcels={data.parcels} onState={r=>setData(r.state)} onOpen={id=>{setDemo(false);setSelection(id)}}/>}
 {((page==='search'&&!simpleMode)||page==='favorites')&&<><div className="summary-grid"><Metric icon={MapPin} label={demo?'В подборке · демо':'Уникальных участков'} value={demo?8:stats.parcels} sub="В границах населённых пунктов"/><Metric icon={ShieldCheck} label="Вариантов поиска" value="2" sub="Образование и готовые участки" color="blue"/><Metric icon={Compass} label="Регионов для поиска" value="9" sub="От Калуги до Тюмени" color="orange"/></div><div className="search-workspace"><aside className={'filter-panel '+(mobileFilters?'mobile-open':'')}><div className="filter-title"><span><SlidersHorizontal size={17}/>Параметры поиска</span><button className="icon-btn mobile-only" onClick={()=>setMobileFilters(false)} aria-label="Закрыть фильтры"><X size={18}/></button></div><div className="filter-body"><label className="field-label">Что ищем</label><div className="type-options"><button className={kind==='unformed'?'chosen':''} onClick={()=>{setKind('unformed');setSelection(null)}}><span className="radio"/><div><b>Территории</b><small>Для образования участка</small></div><Square size={17}/></button><button className={kind==='formed'?'chosen':''} onClick={()=>{setKind('formed');setSelection(null)}}><span className="radio"/><div><b>Готовые участки</b><small>С кадастровым номером</small></div><Layers size={17}/></button></div><label className="field-label" htmlFor="region">Регион</label><div className="select-wrap"><MapPin size={15}/><select id="region" value={region} onChange={e=>{setRegion(e.target.value);setBounds(null);setTerritory('');setSelection(null)}}>{REGIONS.map(r=><option key={r}>{r}</option>)}</select></div><label className="field-label" htmlFor="territory">Район или населённый пункт</label><input id="territory" placeholder="Название территории" value={territory} onChange={e=>setTerritory(e.target.value)}/><button className={'map-select '+(draw?'chosen':'')} onClick={()=>{setDraw(!draw);setView('split');setMobileFilters(false)}}><Square size={15}/>{draw?'Выбери две точки на карте':'Выделить область на карте'}</button>{bounds&&<div className="bounds-note">Область на карте задана<button onClick={()=>setBounds(null)} aria-label="Снять область"><X size={14}/></button></div>}<div className="filter-divider"/><label className="field-label">Площадь участка <span>соток</span></label><div className="area-fields"><label><small>от</small><input aria-label="Минимальная площадь" type="number" min="6" max="20" value={minArea} onChange={e=>setMinArea(e.target.value)}/></label><span>—</span><label><small>до</small><input aria-label="Максимальная площадь" type="number" min="6" max="20" value={maxArea} onChange={e=>setMaxArea(e.target.value)}/></label></div><div className="range-visual"><span/></div><label className="field-label">Вид использования</label>{USAGES.map((u,i)=><label className="checkbox" key={u}><input type="checkbox" checked={usages.includes(u)} onChange={()=>setUsages(usages.includes(u)?usages.filter(x=>x!==u):[...usages,u])}/><span>{u==='ЛПХ'?'Приусадебное ЛПХ':u}</span></label>)}<div className="fixed-filters"><ShieldCheck size={15}/><div>Участки 6–20 соток<small>В границах населённых пунктов</small></div></div><button className="btn primary search-btn" disabled={busy} onClick={run(search)}>{busy?<Loader2 className="spin" size={17}/>:<Search size={17}/>}Найти участки<ArrowRight size={16}/></button><button className="reset-btn" onClick={()=>{setMinArea(6);setMaxArea(20);setUsages([...USAGES]);setTerritory('');setBounds(null);setQuery('')}}>Сбросить фильтры</button></div><div className="filter-foot"><Info size={14}/>Результаты требуют проверки перед подачей заявления</div></aside>
 <section className="results-panel"><div className="results-toolbar"><div className="results-title"><h2>{page==='favorites'?'Избранные участки':'Результаты поиска'}</h2><span className="count">{parcels.length}</span>{demo&&<span className="tiny-demo">ДЕМО</span>}</div><div className="view-toggle">{[['map',Map,'Карта'],['table',List,'Таблица'],['split',LayoutGrid,'Вместе']].map(([v,I,t])=><button key={v} title={t} className={view===v?'active':''} onClick={()=>setView(v)}><I size={16}/><span>{t}</span></button>)}</div></div><div className="results-subbar"><div className="result-caption"><span className="dot"/>{demo?'Учебная подборка':searchResult?searchResult.status==='unavailable'?'Источники требуют подключения':'Поиск завершён':'Сохранённые варианты'}</div><button className="filter-mobile-btn" onClick={()=>setMobileFilters(true)}><SlidersHorizontal size={15}/>Фильтры</button><select aria-label="Сортировка" value={sort} onChange={e=>setSort(e.target.value)}><option value="default">По умолчанию</option><option value="profit">По расчётной прибыли</option><option value="area">По площади</option></select></div>
 {view!=='table'&&<MapView parcels={parcels} region={region} selected={selection} onSelect={setSelection} draw={draw} bounds={bounds} onBounds={b=>{setBounds(b);setDraw(false)}} demo={demo} full={view==='map'}/>}
 {view!=='map'&&<><div className="table-top"><span><span className="table-green-line"/>Участки <b>{parcels.length}</b></span><div className="table-search"><Search size={14}/><input placeholder="Найти в результатах" aria-label="Поиск в результатах" value={query} onChange={e=>setQuery(e.target.value)}/></div></div><div className="table-wrap"><table className="parcels-table"><thead><tr><th>УЧАСТОК / ЛОКАЦИЯ</th><th>ПЛОЩАДЬ</th><th>ВРИ</th><th>ЛИКВИДНОСТЬ</th><th>ПРИБЫЛЬ, ОЦЕНКА</th><th/></tr></thead><tbody>{parcels.map((p,i)=>{const c=calculate(p);return <tr key={p.id} className={selection===p.id?'selected':''} onClick={()=>setSelection(p.id)} tabIndex="0" onKeyDown={e=>{if(e.key==='Enter')setSelection(p.id)}}><td><div className="location-cell"><span className="parcel-number">{String(i+1).padStart(2,'0')}</span><div><b>{p.settlement}</b><small>{p.id} · {p.demo?'Условная территория':p.address}</small></div></div></td><td><b>{p.area}</b><small> сот.</small></td><td><span className="usage-pill">{p.usage}</span></td><td><span className={'liquidity '+(c.deals<3?'low':'')}><span className="dot"/>{c.deals<3?'Мало данных':c.deals+' сделки'}</span></td><td><b className="profit-text">{money(c.profit)}</b><small className="estimate-label">{p.demo?'Демо-расчёт':'Предварительно'}</small></td><td><button className={'icon-btn favorite '+(p.favorite?'is-favorite':'')} aria-label={p.favorite?'Убрать из избранного':'В избранное'} onClick={e=>{e.stopPropagation();favorite(p)}}><Heart size={17} fill={p.favorite?'currentColor':'none'}/></button></td></tr>})}</tbody></table>{!parcels.length&&<div className="empty"><Search size={30}/><h3>Здесь появятся найденные участки</h3><p>{searchResult?.message||'Выбери территорию и запусти поиск. Для реального поиска нужно подключить источник данных.'}</p><button className="btn secondary" onClick={()=>setPage('settings')}>Посмотреть источники <ArrowRight size={15}/></button></div>}</div></>}
 <div className="results-footer"><span>{demo?'Все сведения в подборке вымышлены':'Сведения сохраняются в твоём кабинете'}</span><span><ShieldCheck size={13}/>Источники и даты — в карточке</span></div></section></div><div className="below-note"><Info size={15}/><span>Навигатор помогает отобрать варианты. Возможность предоставления участка подтверждается отдельно.</span><button onClick={()=>setPage('settings')}>Об источниках <ArrowUpRight size={14}/></button></div></>}
 {page==='history'&&<div className="panel"><PanelHeading title="Сохранённые поиски" subtitle="Рабочие запуски сохраняются автоматически"/><div className="table-wrap"><table><thead><tr><th>Дата</th><th>Территория</th><th>Тип</th><th>Найдено</th><th>Состояние</th><th/></tr></thead><tbody>{data.searches.map(s=><tr key={s.id}><td>{date(s.createdAt)}</td><td><b>{s.filters.region}</b><small className="block">{s.filters.territory||'Вся выбранная территория'}</small></td><td>{s.filters.kind==='formed'?'Образованные':'Для образования'}</td><td>{s.parcelIds?.length||0}</td><td><span className="pill orange">{s.status==='unavailable'?'Источник недоступен':'Завершён'}</span></td><td><button className="text-link" onClick={()=>{setDemo(false);setRegion(s.filters.region);setTerritory(s.filters.territory||'');setKind(s.filters.kind);setUsages(s.filters.usages);setMinArea(s.filters.minArea);setMaxArea(s.filters.maxArea);setBounds(s.filters.bounds||null);setSearchResult(s);setPage('search')}}>Открыть <ArrowUpRight size={14}/></button></td></tr>)}</tbody></table></div>{!data.searches.length&&<Empty icon={History} title="История начнётся с первого поиска" text="В рабочем режиме каждый запуск сохраняется вместе с параметрами и состоянием источников." action={()=>{setDemo(false);setPage('search')}} button="Перейти к поиску"/>}</div>}
 {page==='applications'&&<><div className="summary-grid"><Metric icon={FolderOpen} label="Подано заявлений" value={stats.apps} sub="Новая история · без импорта старых данных"/><Metric icon={CheckCircle2} label="Предварительных согласований" value={stats.agreed} sub="Не равно получению участка" color="blue"/><Metric icon={FileText} label="Получено отказов" value={stats.refused} sub="Только подтверждённые решения" color="orange"/></div><div className="panel"><PanelHeading title="Реестр заявлений" subtitle="Загрузи Excel с ID участка, номером и датой заявления" action={<button className="btn primary" onClick={()=>xlsxRef.current.click()}><Upload size={16}/>Загрузить Excel</button>}/><div className="table-wrap"><table><thead><tr><th>Участок</th><th>Номер заявления</th><th>Дата подачи</th><th>Этап</th><th>Последнее решение</th></tr></thead><tbody>{data.applications.map(a=><tr key={a.id} onClick={()=>{setDemo(false);setRegion(data.parcels.find(p=>p.id===a.parcelId)?.region||region);setSelection(a.parcelId)}}><td><b>{a.parcelId}</b></td><td>{a.number}</td><td>{date(a.submittedAt)}</td><td><span className={'pill '+(a.stage==='Отказ'?'orange':'green')}>{a.stage}</span></td><td>{date(a.decisionDate)}</td></tr>)}</tbody></table></div>{!data.applications.length&&<Empty icon={FolderOpen} title="Твоя новая история заявлений" text="Сначала сохрани участок и выгрузи Excel. После подачи заполни номер и дату, затем загрузи таблицу обратно."/>}</div></>}
 {page==='documents'&&<div className="panel"><PanelHeading title="Ответы администраций" subtitle="Текстовые PDF · до 10 МБ каждый · сохранение после проверки" action={<button className="btn primary" disabled={docsBusy} onClick={()=>pdfRef.current.click()}>{docsBusy?<Loader2 className="spin" size={16}/>:<Upload size={16}/>}Загрузить PDF</button>}/><div className="notice subtle"><Info size={18}/><div>Программа предлагает данные из текста. Даты, связь с заявлением и основание нужно проверить. Скан без текстового слоя потребует ручного заполнения.</div></div>{pending.length>0&&<div className="bulk-bar"><label className="checkbox"><input type="checkbox" checked={pending.length>0&&pickedDocs.length===pending.length} onChange={e=>setPickedDocs(e.target.checked?pending.map(d=>d.id):[])}/>Выбрать ожидающие</label><button className="btn secondary" disabled={!pickedDocs.length} onClick={run(async()=>{await mutate('confirmDocuments',{ids:pickedDocs});setPickedDocs([]);setToast('Проверенные документы сохранены');})}><CheckCheck size={16}/>Подтвердить выбранные ({pickedDocs.length})</button></div>}{data.documents.map(d=><div className="document-row" key={d.id}><input type="checkbox" aria-label="Выбрать документ" disabled={d.confirmed} checked={pickedDocs.includes(d.id)} onChange={e=>setPickedDocs(e.target.checked?[...pickedDocs,d.id]:pickedDocs.filter(x=>x!==d.id))}/><div className="file-icon"><FileText size={22}/></div><div className="document-name"><b>{d.name}</b><small>{date(d.createdAt)} · {d.fields.applicationNumber||'Номер заявления не распознан'}</small></div><span className={'pill '+(d.confirmed?'green':'orange')}>{d.confirmed?'Подтверждён':'Ожидает проверки'}</span><button className="btn secondary" onClick={()=>setReview(structuredClone(d))}>{d.confirmed?'Посмотреть':'Проверить'}<ArrowUpRight size={14}/></button></div>)}{!data.documents.length&&<Empty icon={FileText} title="Загрузи первый ответ администрации" text="Извлечём текст и предложим дату, номер заявления и результат. Ни одно решение не попадёт в статистику без твоего подтверждения." action={()=>pdfRef.current.click()} button="Выбрать PDF"/>}</div>}
 {page==='stats'&&<><div className="summary-grid four"><Metric icon={Search} label="Поисков" value={data.searches.length} sub="Только рабочие запуски"/><Metric icon={MapPin} label="Уникальных участков" value={stats.parcels} sub="Повторные находки не дублируются" color="blue"/><Metric icon={CheckCircle2} label="Согласований" value={stats.agreed} sub={`Из ${stats.apps} заявлений`} /><Metric icon={FileText} label="Отказов" value={stats.refused} sub={`Из ${stats.apps} заявлений`} color="orange"/></div><div className="stats-grid"><div className="panel"><PanelHeading title="По регионам" subtitle="Уникальные участки и поданные заявления"/><div className="region-bars">{REGIONS.map(r=>{const ps=data.parcels.filter(p=>p.region===r&&!p.demo);const apps=data.applications.filter(a=>ps.some(p=>p.id===a.parcelId));return <div className="region-bar" key={r}><div><span>{r.replace(' область',' обл.')}</span><b>{ps.length}<small> / {apps.length} заявл.</small></b></div><div className="track"><span style={{width:stats.parcels?ps.length/stats.parcels*100+'%':'0%'}}/></div></div>})}</div></div><div className="panel"><PanelHeading title="Результаты рассмотрения" subtitle="Предварительное согласование и получение — разные этапы"/><div className="outcomes">{STAGES.map(s=><div key={s}><span>{s}</span><b>{data.applications.filter(a=>a.stage===s).length}</b></div>)}</div><div className="notice subtle"><Info size={17}/><p>Документы на проверке: {pending.length}. Неподтверждённые решения в показатели не включены.</p></div></div><div className="panel"><PanelHeading title="Основания отказов" subtitle="Сохраняем формулировку из подтверждённого документа"/>{data.documents.filter(d=>d.confirmed&&d.fields.stage==='Отказ').map(d=><div className="reason-item" key={d.id}><b>{d.fields.parcelId}</b><p>{d.fields.reason||'Основание не указано'}</p></div>)}{!stats.refused&&<Empty icon={BarChart3} title="Данных пока нет" text="После подтверждения ответов здесь появятся основания отказов."/>}</div></div></>}
 {page==='settings'&&<>{user?.auth==='password'&&<NspdPanel/>}{user?.auth==='password'&&<div className="panel"><PanelHeading title="Почта и подтверждение" subtitle={user.emailVerifiedAt?'Адрес электронной почты подтверждён':'Подключение Mail.ru и письмо для существующего кабинета'} action={<a className="btn secondary" href="/account/email"><FileText size={16}/>Настроить почту</a>}/></div>}<div className="notice warning"><AlertTriangle size={18}/><div><b>Автоматические источники ещё не подключены</b><p>Кнопка реального поиска сохраняет запуск и состояние доступа. Вымышленные участки появляются только в демонстрационном режиме.</p></div></div><div className="sources-grid">{SOURCES.map((s,i)=><div className="panel source-card" key={s.id}><div className="source-top"><span className={'source-logo s'+i}>{s.id==='nspd'?<Layers size={23}/>:s.id==='deals'?<FileText size={23}/>:s.name.slice(0,1)}</span><span className="pill orange">Не подключён</span></div><h3>{s.name}</h3><p>{s.description}</p><small>{s.id==='cntd'?'Требуется проверить API и условия личного кабинета. Актуальность норм не подтверждается автоматически.':s.id==='deals'?'Нужен подтверждённый способ получения сделок из бота.':s.id==='nspd'?'Нужен проверенный источник геометрии и правовых сведений.':'Требуется подтвердить доступ к рыночным объявлениям.'}</small><a href={s.url} target="_blank" rel="noreferrer">Открыть источник <ArrowUpRight size={15}/></a></div>)}</div><div className="panel"><PanelHeading title="Работа со своими данными" subtitle="Дополнительный способ наполнить кабинет до подключения источников"/><div className="settings-actions"><button className="btn secondary" onClick={()=>{setManual({...manual,region});setModal({type:'manual'})}}><Plus size={16}/>Добавить участок вручную</button><button className="btn secondary" onClick={()=>geoRef.current.click()}><Upload size={16}/>Импорт GeoJSON</button><button className="btn secondary" onClick={run(async()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});download(blob,'zemlya-backup.json');setToast('Резервная копия данных скачана');})}><Download size={16}/>Резервная копия</button></div><div className="notice subtle"><ShieldCheck size={18}/><div><b>Закрытый доступ</b><p>Размещённая версия защищена входом через ChatGPT. Локальная версия поддерживает почту и пароль. Пользовательские документы не публикуются в GitHub.</p></div></div></div></>}
 </>}
 <footer className="page-footer"><span>Земля · Навигатор</span><span>Взвешенные решения начинаются с данных</span><span>Первая версия · 9 регионов</span></footer></div></main>
 {selected&&<ParcelCard initialTab={simpleMode?'economics':'overview'} parcel={{...selected,favorite:selected.demo?savedDemo.current.has(selected.id):selected.favorite}} onClose={()=>setSelection(null)} onFavorite={favorite} onExcel={run(()=>excelExport([selected]))} onPDF={run(()=>printParcel(selected))} applications={data.applications.filter(a=>a.parcelId===selected.id)} onStage={run(async(id,stage)=>{await mutate('stage',{id,stage});setToast('Этап обновлён');})} onSave={run(async changes=>{if(selected.demo){setToast('В демо-режиме изменения не записываются в рабочую базу');return;}await mutate('updateParcel',{id:selected.id,...changes});setToast('Карточка и версия расчёта сохранены');})}/>}
 {review&&<Modal title="Проверка ответа администрации" onClose={()=>setReview(null)} wide><div className="review-layout"><div><div className="notice warning"><Info size={17}/><p>Сверь данные с исходным PDF. Дата документа и получения ответа — разные поля.</p></div>{[['parcelId','Участок'],['applicationNumber','Номер заявления'],['date','Дата документа'],['receivedAt','Дата получения'],['authority','Орган, выдавший ответ']].map(([k,l])=><label className="form-field" key={k}>{l}{k==='parcelId'?<select disabled={review.confirmed} value={review.fields[k]} onChange={e=>setReview({...review,fields:{...review.fields,[k]:e.target.value}})}><option value="">Выбери участок</option>{data.parcels.filter(p=>!p.demo).map(p=><option value={p.id} key={p.id}>{p.id} · {p.settlement}</option>)}</select>:<input disabled={review.confirmed} type={k==='date'||k==='receivedAt'?'date':'text'} value={review.fields[k]||''} onChange={e=>setReview({...review,fields:{...review.fields,[k]:e.target.value}})}/>}</label>)}<label className="form-field">Результат<select disabled={review.confirmed} value={review.fields.stage} onChange={e=>setReview({...review,fields:{...review.fields,stage:e.target.value}})}>{STAGES.filter(s=>s!=='Заявление подано').map(s=><option key={s}>{s}</option>)}</select></label><label className="form-field">Основание / формулировка<textarea disabled={review.confirmed} rows="5" value={review.fields.reason||''} onChange={e=>setReview({...review,fields:{...review.fields,reason:e.target.value}})}/></label>{!review.confirmed&&<div className="modal-actions"><button className="btn secondary" onClick={run(async()=>{await mutate('editDocument',{id:review.id,fields:review.fields});setToast('Черновик сохранён');})}>Сохранить черновик</button><button className="btn primary" onClick={run(async()=>{await mutate('editDocument',{id:review.id,fields:review.fields});await mutate('confirmDocuments',{ids:[review.id]});setReview(null);setToast('Документ подтверждён, заявление обновлено');})}><Check size={16}/>Подтвердить и сохранить</button></div>}</div><div className="pdf-preview"><a className="btn secondary" href={'/api/document/'+review.id} target="_blank" rel="noreferrer"><ExternalLink size={16}/>Открыть исходный PDF</a><iframe title="Исходный PDF" src={'/api/document/'+review.id}/><details><summary>Извлечённый текст</summary><pre>{review.text||'Текст не распознан. Заполни поля вручную.'}</pre></details></div></div></Modal>}
 {modal?.type==='excel'&&<Modal title="Проверь импорт заявлений" onClose={()=>setModal(null)} wide><p className="muted">Нужны столбцы «ID участка», «Номер заявления», «Дата подачи». Неизвестные ID и пустые поля не записываются.</p><div className="table-wrap"><table><thead><tr><th>ID участка</th><th>Номер</th><th>Дата</th><th>Проверка</th></tr></thead><tbody>{modal.rows.slice(0,200).map((r,i)=><tr key={i}><td>{String(r['ID участка']||'—')}</td><td>{String(r['Номер заявления']||'—')}</td><td>{String(r['Дата подачи'] instanceof Date?r['Дата подачи'].toLocaleDateString('ru-RU'):r['Дата подачи']||'—')}</td><td>{data.parcels.some(p=>!p.demo&&p.id===r['ID участка'])?'ID найден':'Неизвестный ID'}</td></tr>)}</tbody></table></div><p>Строк: {modal.rows.length}. Уже загруженные заявления будут обновлены без дублей.</p><button className="btn primary" onClick={run(async()=>{const r=await mutate('importApplications',{rows:modal.rows});setModal({type:'importResult',result:r});setPage('applications')})}><Check size={16}/>Подтвердить импорт</button></Modal>}
 {modal?.type==='importResult'&&<Modal title="Результат импорта" onClose={()=>setModal(null)}><h3>Сохранено: {modal.result.imported}</h3><p>Пропущено: {modal.result.errors.length}</p>{modal.result.errors.map((x,i)=><div className="notice warning" key={i}>Строка {x.row}: {x.error}</div>)}<button className="btn primary" onClick={()=>setModal(null)}>Готово</button></Modal>}
 {modal?.type==='manual'&&<Modal title="Добавить участок" onClose={()=>setModal(null)}><p className="muted">Это ручная запись. Доступность и ограничения будут отмечены как непроверенные.</p><div className="form-grid">{[['region','Регион'],['settlement','Населённый пункт'],['address','Описание расположения'],['area','Площадь, соток'],['usage','ВРИ'],['kind','Тип участка'],['lat','Широта'],['lng','Долгота']].map(([k,l])=><label className="form-field" key={k}>{l}{['region','usage','kind'].includes(k)?<select value={manual[k]} onChange={e=>setManual({...manual,[k]:e.target.value})}>{(k==='region'?REGIONS:k==='usage'?USAGES:['unformed','formed']).map(v=><option value={v} key={v}>{v==='unformed'?'Для образования':v==='formed'?'Образованный':v}</option>)}</select>:<input type={['area','lat','lng'].includes(k)?'number':'text'} step="any" value={manual[k]} onChange={e=>setManual({...manual,[k]:e.target.value})}/>}</label>)}</div><button className="btn primary" onClick={run(addManual)}><Plus size={16}/>Сохранить участок</button></Modal>}
 <input hidden ref={xlsxRef} type="file" accept=".xlsx,.xls" onChange={run(importExcel)}/><input hidden ref={pdfRef} type="file" accept="application/pdf,.pdf" multiple onChange={run(uploadPDF)}/><input hidden ref={geoRef} type="file" accept=".geojson,.json" onChange={run(importGeo)}/>{toast&&<div className="toast" role="status"><Info size={18}/><span>{toast}</span><button onClick={()=>setToast('')} aria-label="Закрыть уведомление"><X size={16}/></button></div>}
 </div>;
}
function Metric({icon:Icon,label,value,sub,color='green'}){return <div className={'metric-card '+color}><div className="metric-copy"><span>{label}</span><strong>{value}</strong><small>{sub}</small></div><div className="metric-icon"><Icon size={22}/></div><div className="metric-spark"><i/><i/><i/><i/><i/><i/></div></div>}
function PanelHeading({title,subtitle,action}){return <div className="panel-heading"><div><h2>{title}</h2><p>{subtitle}</p></div>{action}</div>}
function Empty({icon:Icon,title,text,action,button}){return <div className="empty"><Icon size={30}/><h3>{title}</h3><p>{text}</p>{action&&<button className="btn secondary" onClick={action}>{button}<ArrowRight size={15}/></button>}</div>}
function Modal({title,onClose,children,wide}){useEffect(()=>{const fn=e=>{if(e.key==='Escape')onClose()};document.addEventListener('keydown',fn);const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',fn);document.body.style.overflow=old}},[]);return <div className="modal-backdrop" onClick={onClose}><section role="dialog" aria-modal="true" aria-label={title} className={'modal '+(wide?'wide':'')} onClick={e=>e.stopPropagation()}><header><h2>{title}</h2><button className="icon-btn" onClick={onClose} aria-label="Закрыть"><X size={21}/></button></header><div className="modal-content">{children}</div></section></div>}
function download(blob,name){const a=document.createElement('a');const u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function MapView({parcels,region,selected,onSelect,draw,onBounds,bounds,demo,full}){
 const el=useRef(),map=useRef(),layers=useRef(),rect=useRef(),first=useRef(null),drawRef=useRef(draw),boundsCb=useRef(onBounds);useEffect(()=>{drawRef.current=draw;first.current=null;if(map.current)map.current.getContainer().style.cursor=draw?'crosshair':'';},[draw]);boundsCb.current=onBounds;
 useEffect(()=>{map.current=L.map(el.current,{zoomControl:false,attributionControl:true,scrollWheelZoom:false}).setView(CENTERS[REGIONS.indexOf(region)],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map.current);layers.current=L.layerGroup().addTo(map.current);map.current.on('click',e=>{if(!drawRef.current)return;if(!first.current){first.current=e.latlng;return;}const b=L.latLngBounds(first.current,e.latlng);boundsCb.current({south:b.getSouth(),north:b.getNorth(),west:b.getWest(),east:b.getEast()});first.current=null;});return()=>map.current?.remove();},[]);
 useEffect(()=>{if(map.current){map.current.setView(CENTERS[REGIONS.indexOf(region)],11);}},[region]);
 useEffect(()=>{if(!layers.current)return;layers.current.clearLayers();parcels.forEach((p,i)=>{const isSelected=p.id===selected;const marker=L.marker([p.lat,p.lng],{icon:L.divIcon({className:'custom-marker '+(isSelected?'marker-selected':''),html:`<span>${String(i+1).padStart(2,'0')}</span>`,iconSize:[34,39],iconAnchor:[17,39]})}).addTo(layers.current);marker.on('click',()=>{if(!drawRef.current)onSelect(p.id)});if(p.geometry){L.geoJSON(p.geometry,{style:{color:isSelected?'#ef963c':'#207b57',weight:2,fillColor:'#76a785',fillOpacity:.23}}).addTo(layers.current).on('click',()=>{if(!drawRef.current)onSelect(p.id)});}});},[parcels,selected]);
 useEffect(()=>{if(rect.current)rect.current.remove();if(bounds&&map.current)rect.current=L.rectangle([[bounds.south,bounds.west],[bounds.north,bounds.east]],{color:'#377cba',weight:2,dashArray:'6 4',fillOpacity:.06,interactive:false}).addTo(map.current);},[bounds]);
 useEffect(()=>{const t=setTimeout(()=>map.current?.invalidateSize(),150);return()=>clearTimeout(t);},[full]);
 return <div className={'map-container '+(full?'full':'')}><div ref={el} className="leaflet-map"/><div className="map-label"><MapPin size={14}/>{region}<span>{demo?'Учебные отметки':'Карта расположения'}</span></div><div className="map-controls"><button title="Приблизить" onClick={()=>map.current.zoomIn()}><Plus size={19}/></button><button title="Отдалить" onClick={()=>map.current.zoomOut()}><Minus size={19}/></button><button title="К выбранному региону" onClick={()=>map.current.setView(CENTERS[REGIONS.indexOf(region)],11)}><LocateFixed size={18}/></button></div><div className="map-compass"><span>С</span><Compass size={27}/></div><div className="map-legend"><span><i className="legend-parcel"/>Кандидат на проверку</span><span><i className="legend-warning"/>Не подтверждён</span></div>{draw&&<div className="map-instruction"><Square size={16}/>Нажми два противоположных угла области</div>}<div className="map-scale">500 м <span/></div></div>;
}
function ParcelCard({parcel:p,initialTab='overview',onClose,onFavorite,onExcel,onPDF,onSave,applications,onStage}){
 const [tab,setTab]=useState(initialTab),[economics,setEconomics]=useState(p.economics||{}),[analogs,setAnalogs]=useState(p.analogs||[]),[note,setNote]=useState(p.note||'');useEffect(()=>{setEconomics(p.economics||{});setAnalogs(p.analogs||[]);setNote(p.note||'');setTab(initialTab);},[p.id,initialTab]);useEffect(()=>{const f=e=>{if(e.key==='Escape')onClose()};document.addEventListener('keydown',f);return()=>document.removeEventListener('keydown',f)},[]);const c=calculate({...p,economics,analogs});const setE=(k,v)=>setEconomics({...economics,[k]:v});
 return <div className="drawer-backdrop" onClick={onClose}><aside className="parcel-drawer" role="dialog" aria-modal="true" aria-label="Карточка участка" onClick={e=>e.stopPropagation()}><header className="drawer-header"><div><span className="eyebrow">КАРТОЧКА УЧАСТКА</span><h2>{p.settlement}</h2><p>{p.id} · {p.region}</p></div><button className="icon-btn" onClick={onClose} aria-label="Закрыть карточку"><X/></button></header><div className="drawer-actions"><button className={'btn secondary '+(p.favorite?'is-favorite':'')} onClick={()=>onFavorite(p)}><Heart size={16} fill={p.favorite?'currentColor':'none'}/>{p.favorite?'В избранном':'В избранное'}</button><button className="btn secondary" onClick={onExcel}><Download size={16}/>Excel</button><button className="btn secondary" onClick={onPDF}><FileText size={16}/>PDF / печать</button></div>{p.demo&&<div className="notice warning compact"><Info size={17}/><p>Демонстрационный участок. Сведения и расчёты вымышлены.</p></div>}<div className="drawer-tabs">{[['overview','Обзор'],['checks','Проверки'],['economics','Экономика'],['applications','Заявления']].map(([id,t])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{t}</button>)}</div><div className="drawer-body">
 {tab==='overview'&&<><div className="parcel-overview-art"><div className="art-grid"/><div className="art-parcel"><span>{p.area}<small>соток</small></span></div><span className="art-coordinate">{Number(p.lat).toFixed(5)}, {Number(p.lng).toFixed(5)}</span><span className="art-north">С ↑</span></div><div className="detail-facts">{[['Расположение',p.address],['Площадь',p.area+' соток / '+p.area*100+' м²'],['Использование',p.usage],['Тип',p.kind==='formed'?'Образованный участок':'Территория для образования'],['Кадастровый номер',p.cadastre||'Участок ещё не образован'],['Собственность',p.ownership||'Требует проверки'],['Добавлен',date(p.createdAt)]].map(([k,v])=><div key={k}><span>{k}</span><b>{v}</b></div>)}</div><a className="text-link" target="_blank" rel="noreferrer" href={`https://nspd.gov.ru/map?thematic=PKK&zoom=16&coordinate_x=${p.lng}&coordinate_y=${p.lat}`}>Открыть НСПД <ArrowUpRight size={15}/></a><div className="notice subtle"><Info size={17}/><p>Предварительный контур не является официальной схемой. Доступность предоставления требует подтверждения.</p></div><label className="form-field">Мои заметки<textarea rows="4" value={note} onChange={e=>setNote(e.target.value)} placeholder="Что важно учесть по этому участку"/></label><button className="btn primary" onClick={()=>onSave({note,economics,analogs})}>Сохранить заметку</button></>}
 {tab==='checks'&&<><div className="notice warning"><AlertTriangle size={18}/><p>Без проверенного источника сведения не считаются подтверждёнными.</p></div>{p.checks.map((x,i)=><div className="check-row" key={x.name}><span className={'check-icon '+(x.status==='warning'?'orange':'blue')}>{x.status==='warning'?<AlertTriangle size={18}/>:<Info size={18}/>}</span><div><b>{x.name}</b><p>{x.detail}</p><small>Источник: {safeURL(x.source)?<a href={x.source} target="_blank" rel="noreferrer">Открыть</a>:x.source||'не указан'} · {x.checkedAt?date(x.checkedAt):'дата не подтверждена'}</small></div><span className={'pill '+(x.status==='warning'?'orange':'neutral')}>{x.status==='warning'?'Ограничение':'Проверить'}</span></div>)}</>}
 {tab==='economics'&&<><p className="muted">Площадь выбранного контура: {p.area} соток. Расчёт сохраняется отдельно для этого варианта.</p><div className="calc-metrics"><div><span>Цена права аренды</span><strong>{money(c.price)}</strong></div><div><span>Расходы</span><strong>{money(c.total)}</strong></div><div className="highlight"><span>Расчётная чистая прибыль</span><strong>{money(c.profit)}</strong></div><div><span>Доходность за сделку</span><strong>{c.roi==null?'Нет данных':fmt.format(c.roi)+'%'}</strong></div></div><div className="formula-box">Меньшая медиана за сотку × 0,8 ÷ 2 × {p.area} соток<small>Пользовательская модель предварительной оценки</small></div>{c.missingCosts.length>0&&<div className="notice subtle"><Info size={16}/><p>Для итоговой прибыли заполни: {c.missingCosts.map(k=>k==='rent'?'годовую аренду':k==='commission'?'комиссию':costLabels[k]).join(', ')}. Если расхода нет, укажи 0 явно.</p></div>}{c.deals<3&&<div className="notice warning"><AlertTriangle size={17}/><p>Недостаточно данных для оценки ликвидности: {c.deals} из 3 сопоставимых сделок за последние 12 месяцев.</p></div>}<h3>Источники цены</h3>{c.groups.map(g=><div className="source-price" key={g.source}><span>{g.source}<small>{g.count} записей</small></span><b>{money(g.median)}<small>за сотку</small></b></div>)}<details className="calc-details" open={c.price===null?true:undefined}><summary>Аналоги и сделки ({analogs.length})</summary>{analogs.map((a,i)=><div className="analog-edit" key={i}><div className="form-grid"><label className="form-field">Источник<select value={a.source} onChange={e=>setAnalogs(analogs.map((x,j)=>i===j?{...x,source:e.target.value}:x))}>{['Авито','ЦИАН','Сделки'].map(s=><option key={s}>{s}</option>)}</select></label>{[['price','Цена всего, ₽'],['area','Площадь, соток'],['date','Дата'],['url','Ссылка / идентификатор']].map(([k,l])=><label key={k} className="form-field">{l}<input type={k==='date'?'date':['price','area'].includes(k)?'number':'text'} value={a[k]||''} onChange={e=>setAnalogs(analogs.map((x,j)=>i===j?{...x,[k]:e.target.value}:x))}/></label>)}</div><button className="text-link danger" onClick={()=>setAnalogs(analogs.filter((_,j)=>i!==j))}><Trash2 size={14}/>Удалить</button></div>)}<button className="btn secondary" onClick={()=>setAnalogs([...analogs,{source:'Авито',price:'',area:10,date:new Date().toISOString().slice(0,10),url:'',settlement:p.settlement,usage:p.usage}])}><Plus size={15}/>Добавить аналог</button>{c.excluded.map((a,i)=><p className="muted" key={i}>Исключено: {a.url} — {a.reason}</p>)}</details><h3>Аренда и расходы</h3><label className="form-field">Способ расчёта аренды<select value={economics.rentMode||'manual'} onChange={e=>setE('rentMode',e.target.value)}><option value="manual">Годовая сумма вручную</option><option value="percent">Процент от кадастровой стоимости</option><option value="coeff">Ставка за м² × коэффициент</option></select></label><div className="form-grid">{(economics.rentMode==='manual'||!economics.rentMode?[['rent','Годовая аренда, ₽']]:economics.rentMode==='percent'?[['cadastrePerSotka','Кадастровая стоимость за сотку, ₽'],['rentRate','Ставка, % в год']]:[['rentRate','Ставка, ₽ за м² в год'],['coefficient','Совокупный коэффициент']]).concat(Object.entries(costLabels),[['commission','Комиссия риелтора']]).map(([k,l])=><label className="form-field" key={k}>{l}<input type="number" min="0" step="any" value={economics[k]??''} placeholder="Не указано" onChange={e=>setE(k,e.target.value===''?null:Number(e.target.value))}/></label>)}<label className="form-field">Комиссия<select value={economics.commissionMode||'percent'} onChange={e=>setE('commissionMode',e.target.value)}><option value="percent">% от продажи</option><option value="fixed">Фиксированная сумма, ₽</option></select></label></div><div className="notice subtle"><Info size={17}/><p>В расходы включён полный год аренды. Для несформированного участка кадастровая стоимость — предварительный ориентир по соседним участкам.</p></div><h3>Источник ставки аренды</h3><span className="pill orange">Актуальность автоматически не подтверждена</span>{[['documentTitle','Название, номер и дата акта'],['documentClause','Пункт, приложение и редакция'],['documentUrl','Ссылка на документ']].map(([k,l])=><label className="form-field" key={k}>{l}<input value={economics[k]||''} onChange={e=>setE(k,e.target.value)}/></label>)}<a href="https://docs.cntd.ru/" target="_blank" rel="noreferrer" className="text-link">Открыть Кодекс / Техэксперт <ArrowUpRight size={14}/></a><p className="muted">Источник ставки и её дата сохраняются вместе с расчётом; автоматическая проверка актуальности ставки пока не подключена.</p><button className="btn primary" onClick={()=>onSave({note,economics,analogs})}><Check size={16}/>Сохранить расчёт</button></>}
 {tab==='applications'&&<><div className="notice subtle"><Info size={17}/><p>Выгрузи участок в Excel, сохрани ID, добавь номер и дату подачи. Загрузи заполненный файл в разделе «Заявления».</p></div>{applications.map(a=><div className="application-card" key={a.id}><b>Заявление № {a.number}</b><p>Подано {date(a.submittedAt)} · {a.authority||'Орган не указан'}</p><label className="form-field">Текущий этап<select value={a.stage} onChange={e=>onStage(a.id,e.target.value)}>{STAGES.map(s=><option key={s}>{s}</option>)}</select></label>{a.reason&&<p>{a.reason}</p>}</div>)}{!applications.length&&<Empty icon={FolderOpen} title="Заявлений пока нет" text="После импорта Excel заявление появится здесь."/>}</>}
 </div><div className="drawer-foot"><ShieldCheck size={14}/>Факты, источники и предположения хранятся отдельно</div></aside></div>;
}
createRoot(document.getElementById('root')).render(<App/>);
